import ast
from pathlib import Path
from types import SimpleNamespace
import numpy as np
import pytest
from numpy.testing import assert_array_equal
source = ast.parse(Path('lib/matplotlib/cbook.py').read_text())
node = next(n for n in source.body if isinstance(n, ast.FunctionDef) and n.name == 'safe_masked_invalid')
namespace = {'np': np}
exec(compile(ast.Module(body=[node], type_ignores=[]), 'lib/matplotlib/cbook.py', 'exec'), namespace)
tests = ast.parse(Path('lib/matplotlib/tests/test_cbook.py').read_text())
test = next(n for n in tests.body if isinstance(n, ast.FunctionDef) and n.name == 'test_safe_masked_invalid_mask_preserved')
namespace.update(cbook=SimpleNamespace(safe_masked_invalid=namespace['safe_masked_invalid']), pytest=pytest, assert_array_equal=assert_array_equal)
exec(compile(ast.Module(body=[test], type_ignores=[]), 'lib/matplotlib/tests/test_cbook.py', 'exec'), namespace)
failures = []
for copy in [False, True]:
 for readonly in [False, True]:
  for invalid in [False, True]:
   try:
    namespace[test.name](copy, readonly, invalid)
   except Exception as exc:
    failures.append((copy, readonly, invalid, type(exc).__name__, str(exc)))
print('NumPy', np.__version__)
print('Passed:', 8 - len(failures), 'Failed:', len(failures))
for failure in failures: print(failure)
raise SystemExit(bool(failures))

